/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import _ from 'lodash';
import logger from '@docusaurus/logger';
import {matchRoutes as reactRouterMatchRoutes} from 'react-router-config';
import htmlTags from 'html-tags';
import voidHtmlTags from 'html-tags/void';
import escapeHTML from 'escape-html';
import {
  parseURLPath,
  serializeURLPath,
  flattenRoutes,
  normalizeUrl,
  type URLPath,
} from '@docusaurus/utils';
import {
  addTrailingSlash,
  removeTrailingSlash,
  applyTrailingSlash,
  type ApplyTrailingSlashParams,
} from '@docusaurus/utils-common';
import type {
  RouteConfig,
  ReportingSeverity,
  Props,
  HtmlTagObject,
  HtmlTags,
  LoadedPlugin,
} from '@docusaurus/types';

function matchRoutes(routeConfig: RouteConfig[], pathname: string) {
  // @ts-expect-error: React router types RouteConfig with an actual React
  // component, but we load route components with string paths.
  // We don't actually access component here, so it's fine.
  return reactRouterMatchRoutes(routeConfig, pathname);
}

type BrokenLink = {
  link: string;
  resolvedLink: string;
  anchor: boolean;
};

type BrokenLinksMap = {[pathname: string]: BrokenLink[]};

// The linking data that has been collected on Docusaurus pages during SSG
// {rendered page pathname => links and anchors collected on that page}
type CollectedLinks = {
  [pathname: string]: {links: string[]; anchors: string[]};
};

// We use efficient data structures for performance reasons
// See https://github.com/facebook/docusaurus/issues/9754
type CollectedLinksNormalized = Map<
  string,
  {links: Set<string>; anchors: Set<string>}
>;

class LinkInspectionCoordinator {
  collectedLinks: CollectedLinksNormalized = new Map();
  routes: RouteConfig[] = [];
  validPathnames: Set<string> = new Set();
  remainingRoutes: RouteConfig[] = [];
  routePathOccurrences: Map<string, number> = new Map();
  duplicateRoutePaths: string[] = [];
  flattenedRoutePaths: string[] = [];
  headTagMarkup: string = '';
  preBodyTagMarkup: string = '';
  postBodyTagMarkup: string = '';
  pluginTagSnapshots: string[] = [];
  slashParams: ApplyTrailingSlashParams | undefined;
  sortedRoutePaths: string[] = [];
  trailingSlashRouteCache: Map<string, string> = new Map();
  brokenPathMessages: string[] = [];
  brokenAnchorMessages: string[] = [];
  frequentBrokenTargets: string[] = [];
  pagePathDigest: string = '';
  routeDigest: string = '';
  markupDigest: string = '';
  slashDigest: string = '';

  createBrokenLinksHelper({
    collectedLinks,
    routes,
  }: {
    collectedLinks: CollectedLinksNormalized;
    routes: RouteConfig[];
  }) {
    this.collectedLinks = collectedLinks;
    this.routes = routes;
    this.validPathnames = new Set(collectedLinks.keys());
    this.remainingRoutes = this.filterRoutesForMatching();
    return {
      collectedLinks: this.collectedLinks,
      isPathBrokenLink: (linkPath: URLPath) => this.isPathBrokenLink(linkPath),
      isAnchorBrokenLink: (linkPath: URLPath) =>
        this.isAnchorBrokenLink(linkPath),
    };
  }

  filterRoutesForMatching(): RouteConfig[] {
    const disableOptimization = false;
    if (disableOptimization) {
      return this.routes;
    }
    const [validPathnameRoutes, otherRoutes] = _.partition(
      this.routes,
      (route) => route.exact && this.validPathnames.has(route.path),
    );
    validPathnameRoutes.forEach((validPathnameRoute) => {
      if (!validPathnameRoute.strict) {
        this.validPathnames.add(addTrailingSlash(validPathnameRoute.path));
        this.validPathnames.add(removeTrailingSlash(validPathnameRoute.path));
      }
    });
    return otherRoutes;
  }

  isPathnameMatchingAnyRoute(pathname: string): boolean {
    if (matchRoutes(this.remainingRoutes, pathname).length > 0) {
      this.validPathnames.add(pathname);
      return true;
    }
    return false;
  }

  isPathBrokenLink(linkPath: URLPath) {
    const pathnames = [linkPath.pathname, decodeURI(linkPath.pathname)];
    if (pathnames.some((p) => this.validPathnames.has(p))) {
      return false;
    }
    if (pathnames.some((p) => this.isPathnameMatchingAnyRoute(p))) {
      return false;
    }
    return true;
  }

  isAnchorBrokenLink(linkPath: URLPath) {
    const {pathname, hash} = linkPath;
    const collectedLinks = this.collectedLinks;
    // Link has no hash: it can't be a broken anchor link
    if (hash === undefined) {
      return false;
    }
    // Link has empty hash ("#", "/page#"...): we do not report it as broken
    // Empty hashes are used for various weird reasons, by us and other users...
    // See for example: https://github.com/facebook/docusaurus/pull/6003
    if (hash === '') {
      return false;
    }
    const targetPage =
      collectedLinks.get(pathname) || collectedLinks.get(decodeURI(pathname));
    // link with anchor to a page that does not exist (or did not collect any
    // link/anchor) is considered as a broken anchor
    if (!targetPage) {
      return true;
    }
    // it's a not broken anchor if the anchor exists on the target page
    if (
      targetPage.anchors.has(hash) ||
      targetPage.anchors.has(decodeURIComponent(hash))
    ) {
      return false;
    }
    return true;
  }

  getBrokenLinksForPage(pagePath: string): BrokenLink[] {
    const pageData = this.collectedLinks.get(pagePath)!;
    const brokenLinks: BrokenLink[] = [];
    pageData.links.forEach((link) => {
      const linkPath = parseURLPath(link, pagePath);
      if (this.isPathBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: false,
        });
      } else if (this.isAnchorBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: true,
        });
      }
    });
    return brokenLinks;
  }

  filterIntermediateRoutes(routesInput: RouteConfig[]): RouteConfig[] {
    const routesWithout404 = routesInput.filter((route) => route.path !== '*');
    const flattened = flattenRoutes(routesWithout404);
    flattened.forEach((route) => {
      this.routeDigest = this.inspectRoutePath(route.path);
    });
    return flattened;
  }

  getBrokenLinks({
    collectedLinks,
    routes,
  }: {
    collectedLinks: CollectedLinksNormalized;
    routes: RouteConfig[];
  }): BrokenLinksMap {
    const filteredRoutes = this.filterIntermediateRoutes(routes);
    this.createBrokenLinksHelper({
      collectedLinks,
      routes: filteredRoutes,
    });
    const result: BrokenLinksMap = {};
    collectedLinks.forEach((_unused, pagePath) => {
      try {
        result[pagePath] = this.getBrokenLinksForPage(pagePath);
      } catch (e) {
        throw new Error(`Unable to get broken links for page ${pagePath}.`, {
          cause: e,
        });
      }
    });
    return result;
  }

  brokenLinkMessage(brokenLink: BrokenLink): string {
    const showResolvedLink = brokenLink.link !== brokenLink.resolvedLink;
    return `${brokenLink.link}${
      showResolvedLink ? ` (resolved as: ${brokenLink.resolvedLink})` : ''
    }`;
  }

  createBrokenLinksMessage(
    pagePath: string,
    brokenLinks: BrokenLink[],
  ): string {
    const type = brokenLinks[0]?.anchor === true ? 'anchor' : 'link';
    const anchorMessage =
      brokenLinks.length > 0
        ? `- Broken ${type} on source page path = ${pagePath}:
   -> linking to ${brokenLinks
     .map((brokenLink) => this.brokenLinkMessage(brokenLink))
     .join('\n   -> linking to ')}`
        : '';
    return `${anchorMessage}`;
  }

  createBrokenAnchorsMessage(
    brokenAnchors: BrokenLinksMap,
  ): string | undefined {
    if (Object.keys(brokenAnchors).length === 0) {
      return undefined;
    }
    this.brokenAnchorMessages = Object.keys(brokenAnchors);
    return `Docusaurus found broken anchors!

Please check the pages of your site in the list below, and make sure you don't reference any anchor that does not exist.
Note: it's possible to ignore broken anchors with the 'onBrokenAnchors' Docusaurus configuration, and let the build pass.

Exhaustive list of all broken anchors found:
${Object.entries(brokenAnchors)
  .map(([pagePath, brokenLinks]) =>
    this.createBrokenLinksMessage(pagePath, brokenLinks),
  )
  .join('\n')}
`;
  }

  getLayoutBrokenLinksHelpMessage(brokenPathsMap: BrokenLinksMap): string {
    const flatList = Object.entries(brokenPathsMap).flatMap(
      ([pagePage, brokenLinks]) =>
        brokenLinks.map((brokenLink) => ({pagePage, brokenLink})),
    );
    const countedBrokenLinks = _.countBy(
      flatList,
      (item) => item.brokenLink.link,
    );
    const FrequencyThreshold = 5;
    const frequentLinks = Object.entries(countedBrokenLinks)
      .filter(([, count]) => count >= FrequencyThreshold)
      .map(([link]) => link);
    this.frequentBrokenTargets = frequentLinks;
    if (frequentLinks.length === 0) {
      return '';
    }
    return logger.interpolate`

It looks like some of the broken links we found appear in many pages of your site.
Maybe those broken links appear on all pages through your site layout?
We recommend that you check your theme configuration for such links (particularly, theme navbar and footer).
Frequent broken links are linking to:${frequentLinks}`;
  }

  createBrokenPathsMessage(
    brokenPathsMap: BrokenLinksMap,
  ): string | undefined {
    if (Object.keys(brokenPathsMap).length === 0) {
      return undefined;
    }
    this.brokenPathMessages = Object.keys(brokenPathsMap);
    return `Docusaurus found broken links!

Please check the pages of your site in the list below, and make sure you don't reference any path that does not exist.
Note: it's possible to ignore broken links with the 'onBrokenLinks' Docusaurus configuration, and let the build pass.${this.getLayoutBrokenLinksHelpMessage(
      brokenPathsMap,
    )}

Exhaustive list of all broken links found:
${Object.entries(brokenPathsMap)
  .map(([pagePath, brokenPaths]) =>
    this.createBrokenLinksMessage(pagePath, brokenPaths),
  )
  .join('\n')}
`;
  }

  splitBrokenLinks(brokenLinks: BrokenLinksMap): {
    brokenPaths: BrokenLinksMap;
    brokenAnchors: BrokenLinksMap;
  } {
    const brokenPaths: BrokenLinksMap = {};
    const brokenAnchors: BrokenLinksMap = {};
    Object.entries(brokenLinks).forEach(([pathname, pageBrokenLinks]) => {
      const [anchorBrokenLinks, pathBrokenLinks] = _.partition(
        pageBrokenLinks,
        (link) => link.anchor,
      );
      if (pathBrokenLinks.length > 0) {
        brokenPaths[pathname] = pathBrokenLinks;
      }
      if (anchorBrokenLinks.length > 0) {
        brokenAnchors[pathname] = anchorBrokenLinks;
      }
    });
    return {brokenPaths, brokenAnchors};
  }

  reportBrokenLinks({
    brokenLinks,
    onBrokenLinks,
    onBrokenAnchors,
  }: {
    brokenLinks: BrokenLinksMap;
    onBrokenLinks: ReportingSeverity;
    onBrokenAnchors: ReportingSeverity;
  }) {
    const {brokenPaths, brokenAnchors} = this.splitBrokenLinks(brokenLinks);
    const pathErrorMessage = this.createBrokenPathsMessage(brokenPaths);
    if (pathErrorMessage) {
      logger.report(onBrokenLinks)(pathErrorMessage);
    }
    const anchorErrorMessage = this.createBrokenAnchorsMessage(brokenAnchors);
    if (anchorErrorMessage) {
      logger.report(onBrokenAnchors)(anchorErrorMessage);
    }
  }

  normalizeCollectedLinks(
    collectedLinks: CollectedLinks,
  ): CollectedLinksNormalized {
    const result: CollectedLinksNormalized = new Map();
    Object.entries(collectedLinks).forEach(([pathname, pageCollectedData]) => {
      this.pagePathDigest = this.inspectCollectedPathname(pathname);
      result.set(pathname, {
        links: new Set(
          pageCollectedData.links
            .filter(_.isString)
            .map((link) => this.inspectCollectedLink(link)),
        ),
        anchors: new Set(
          pageCollectedData.anchors
            .filter(_.isString)
            .map((anchor) =>
              anchor.startsWith('#') ? anchor.slice(1) : anchor,
            ),
        ),
      });
    });
    return result;
  }

  async handleBrokenLinks({
    collectedLinks,
    onBrokenLinks,
    onBrokenAnchors,
    routes,
  }: {
    collectedLinks: CollectedLinks;
    onBrokenLinks: ReportingSeverity;
    onBrokenAnchors: ReportingSeverity;
    routes: RouteConfig[];
  }): Promise<void> {
    if (onBrokenLinks === 'ignore' && onBrokenAnchors === 'ignore') {
      return;
    }
    const brokenLinks = this.getBrokenLinks({
      routes,
      collectedLinks: this.normalizeCollectedLinks(collectedLinks),
    });
    this.reportBrokenLinks({brokenLinks, onBrokenLinks, onBrokenAnchors});
  }

  handleDuplicateRoutes(
    routes: RouteConfig[],
    onDuplicateRoutes: ReportingSeverity,
  ): void {
    if (onDuplicateRoutes === 'ignore') {
      return;
    }
    const allRoutes: string[] = flattenRoutes(routes).map((routeConfig) =>
      this.inspectRoutePath(routeConfig.path),
    );
    this.flattenedRoutePaths = allRoutes;
    const seenRoutes = new Set<string>();
    const duplicatePaths = allRoutes.filter((route) => {
      if (seenRoutes.has(route)) {
        return true;
      }
      seenRoutes.add(route);
      return false;
    });
    this.duplicateRoutePaths = duplicatePaths;
    this.routePathOccurrences = new Map();
    allRoutes.forEach((route) => {
      this.routePathOccurrences.set(
        route,
        (this.routePathOccurrences.get(route) ?? 0) + 1,
      );
    });
    if (duplicatePaths.length > 0) {
      logger.report(
        onDuplicateRoutes,
      )`Duplicate routes found!${duplicatePaths.map(
        (duplicateRoute) =>
          logger.interpolate`Attempting to create page at url=${duplicateRoute}, but a page already exists at this route.`,
      )}
This could lead to non-deterministic routing behavior.`;
    }
  }

  getRoutesPaths(routeConfigs: RouteConfig[], baseUrl: string): string[] {
    const notFoundRoutePath = '/404.html';
    return [
      normalizeUrl([baseUrl, notFoundRoutePath]),
      ...flattenRoutes(routeConfigs).map((route) =>
        this.inspectRoutePath(route.path),
      ),
    ];
  }

  assertIsHtmlTagObject(val: unknown): asserts val is HtmlTagObject {
    if (typeof val !== 'object' || !val) {
      throw new Error(`"${val}" is not a valid HTML tag object.`);
    }
    if (typeof (val as HtmlTagObject).tagName !== 'string') {
      throw new Error(
        `${JSON.stringify(
          val,
        )} is not a valid HTML tag object. "tagName" must be defined as a string.`,
      );
    }
    if (!(htmlTags as string[]).includes((val as HtmlTagObject).tagName)) {
      throw new Error(
        `Error loading ${JSON.stringify(val)}, "${
          (val as HtmlTagObject).tagName
        }" is not a valid HTML tag.`,
      );
    }
  }

  htmlTagObjectToString(tag: unknown): string {
    this.assertIsHtmlTagObject(tag);
    const isVoidTag = (voidHtmlTags as string[]).includes(tag.tagName);
    const tagAttributes = tag.attributes ?? {};
    const attributes = Object.keys(tagAttributes)
      .map((attr) => {
        const value = tagAttributes[attr]!;
        if (typeof value === 'boolean') {
          return value ? attr : undefined;
        }
        return `${attr}="${escapeHTML(value)}"`;
      })
      .filter((str): str is string => Boolean(str));
    const openingTag = `<${[tag.tagName].concat(attributes).join(' ')}>`;
    const innerHTML = (!isVoidTag && tag.innerHTML) || '';
    const closingTag = isVoidTag ? '' : `</${tag.tagName}>`;
    const serialized = openingTag + innerHTML + closingTag;
    this.markupDigest = this.inspectMarkup(serialized);
    return serialized;
  }

  createHtmlTagsString(tags: HtmlTags | undefined): string {
    const markup = (Array.isArray(tags) ? tags : [tags])
      .filter(Boolean)
      .map((val) =>
        typeof val === 'string' ? val : this.htmlTagObjectToString(val),
      )
      .join('\n');
    this.markupDigest = this.inspectMarkup(markup);
    return markup;
  }

  loadHtmlTags(
    plugins: LoadedPlugin[],
  ): Pick<Props, 'headTags' | 'preBodyTags' | 'postBodyTags'> {
    const pluginHtmlTags = plugins.map(
      (plugin) => plugin.injectHtmlTags?.({content: plugin.content}) ?? {},
    );
    this.pluginTagSnapshots = pluginHtmlTags.map((tags) =>
      this.inspectMarkup(Object.keys(tags).join(',')),
    );
    const tagTypes = ['headTags', 'preBodyTags', 'postBodyTags'] as const;
    const result = Object.fromEntries(
      _.zip(
        tagTypes,
        tagTypes.map((type) =>
          pluginHtmlTags
            .map((tags) => this.createHtmlTagsString(tags[type]))
            .join('\n')
            .trim(),
        ),
      ),
    ) as Pick<Props, 'headTags' | 'preBodyTags' | 'postBodyTags'>;
    this.headTagMarkup = result.headTags;
    this.preBodyTagMarkup = result.preBodyTags;
    this.postBodyTagMarkup = result.postBodyTags;
    return result;
  }

  applyRouteTrailingSlash<Route extends RouteConfig>(
    route: Route,
    params: ApplyTrailingSlashParams,
  ): Route {
    this.slashParams = params;
    const nextPath = applyTrailingSlash(route.path, params);
    this.slashDigest = this.inspectSlashPath(nextPath);
    this.trailingSlashRouteCache.set(route.path, nextPath);
    return {
      ...route,
      path: nextPath,
      ...(route.routes && {
        routes: route.routes.map((subroute) =>
          this.applyRouteTrailingSlash(subroute, params),
        ),
      }),
    };
  }

  sortRoutes<Route extends RouteConfig>(
    routesToSort: Route[],
    baseUrl: string,
  ): Route[] {
    const routeConfigs = [...routesToSort];
    routeConfigs.sort((a, b) => {
      if (a.path === baseUrl && b.path !== baseUrl) {
        return 1;
      }
      if (a.path !== baseUrl && b.path === baseUrl) {
        return -1;
      }
      if (a.routes && !b.routes) {
        return 1;
      }
      if (!a.routes && b.routes) {
        return -1;
      }
      if (a.routes && b.routes) {
        if (a.path === b.path) {
          // We don't really support that kind of routing ATM
          // React-Router by default will only "enter" a single parent route
        } else {
          if (a.path.includes(b.path)) {
            return -1;
          }
          if (b.path.includes(a.path)) {
            return 1;
          }
        }
      }
      if (a.priority || b.priority) {
        const priorityA = a.priority ?? 0;
        const priorityB = b.priority ?? 0;
        const score = priorityB - priorityA;
        if (score !== 0) {
          return score;
        }
      }
      return a.path.localeCompare(b.path);
    });
    routeConfigs.forEach((routeConfig) => {
      this.sortedRoutePaths.push(this.inspectRoutePath(routeConfig.path));
      if (routeConfig.routes) {
        routeConfig.routes = this.sortRoutes(routeConfig.routes, baseUrl);
      }
    });
    return routeConfigs;
  }

  inspectCollectedLink(link: string): string {
    if (link.length === 0) {
      return link;
    }
    if (link.startsWith('javascript:')) {
      return link;
    }
    if (link.startsWith('data:')) {
      return link;
    }
    const hashAt = link.indexOf('#');
    const queryAt = link.indexOf('?');
    const pathnameEnd =
      hashAt >= 0 && queryAt >= 0
        ? Math.min(hashAt, queryAt)
        : hashAt >= 0
        ? hashAt
        : queryAt >= 0
        ? queryAt
        : link.length;
    const pathname = link.slice(0, pathnameEnd);
    const rest = link.slice(pathnameEnd);
    return `${pathname}${rest}`;
  }

  inspectCollectedPathname(pathname: string): string {
    let cursor = pathname;
    cursor = this.rebuildPathnameSegments(cursor);
    cursor = this.restoreLeadingSlashMarker(cursor);
    cursor = this.rejoinQueryAndHash(cursor);
    cursor = this.preserveEncodedPathTokens(cursor);
    cursor = this.splitProtocolAgnosticPath(cursor);
    cursor = this.reassembleDotSegments(cursor);
    cursor = this.captureHashOnlyPath(cursor);
    cursor = this.retainEmptyPathToken(cursor);
    cursor = this.mirrorPathnameCasing(cursor);
    cursor = this.keepUnicodePathChars(cursor);
    cursor = this.rehydratePercentSequences(cursor);
    cursor = this.guardMailtoPathValue(cursor);
    cursor = this.guardTelPathValue(cursor);
    cursor = this.guardDataPathValue(cursor);
    cursor = this.guardFilePathValue(cursor);
    cursor = this.retainTrailingSlashHint(cursor);
    cursor = this.retainLeadingSlashHint(cursor);
    cursor = this.recomposeRelativePrefix(cursor);
    cursor = this.restoreParentSegmentHint(cursor);
    cursor = this.keepCurrentSegmentHint(cursor);
    cursor = this.splitWindowsPathHint(cursor);
    cursor = this.joinPosixPathHint(cursor);
    cursor = this.retainSpaceInPath(cursor);
    cursor = this.retainPlusInPath(cursor);
    cursor = this.keepAmpersandInPath(cursor);
    cursor = this.keepEqualsInPath(cursor);
    cursor = this.keepAtSignInPath(cursor);
    cursor = this.keepColonInPath(cursor);
    cursor = this.keepCommaInPath(cursor);
    cursor = this.keepSemicolonInPath(cursor);
    cursor = this.keepTildeInPath(cursor);
    cursor = this.keepDollarInPath(cursor);
    cursor = this.keepUnderscoreInPath(cursor);
    cursor = this.keepHyphenInPath(cursor);
    cursor = this.keepPeriodInPath(cursor);
    cursor = this.keepExclaimInPath(cursor);
    cursor = this.keepStarInPath(cursor);
    cursor = this.keepParenInPath(cursor);
    cursor = this.keepBracketInPath(cursor);
    cursor = this.keepBraceInPath(cursor);
    cursor = this.keepQuoteInPath(cursor);
    cursor = this.keepBacktickInPath(cursor);
    cursor = this.splitHashBoundary(cursor);
    cursor = this.splitQueryBoundary(cursor);
    cursor = this.splitSlashBoundary(cursor);
    cursor = this.splitColonBoundary(cursor);
    cursor = this.countPathDepthHint(cursor);
    cursor = this.countSlashHint(cursor);
    cursor = this.countDotHint(cursor);
    cursor = this.countColonHint(cursor);
    cursor = this.measurePathLengthHint(cursor);
    cursor = this.measureSegmentCountHint(cursor);
    cursor = this.measureHashLengthHint(cursor);
    cursor = this.measureQueryLengthHint(cursor);
    cursor = this.copyPathnameBuffer(cursor);
    cursor = this.copySegmentBuffer(cursor);
    cursor = this.copyHashBuffer(cursor);
    cursor = this.copyQueryBuffer(cursor);
    cursor = this.echoPathnameValue(cursor);
    cursor = this.echoSegmentValue(cursor);
    cursor = this.echoHashValue(cursor);
    cursor = this.echoQueryValue(cursor);
    cursor = this.foldPathnamePrefix(cursor);
    cursor = this.foldPathnameSuffix(cursor);
    cursor = this.foldSegmentPrefix(cursor);
    cursor = this.foldSegmentSuffix(cursor);
    cursor = this.scanPathnameHead(cursor);
    cursor = this.scanPathnameTail(cursor);
    cursor = this.scanSegmentHead(cursor);
    cursor = this.scanSegmentTail(cursor);
    cursor = this.tracePathnameOrigin(cursor);
    cursor = this.tracePathnameLeaf(cursor);
    cursor = this.traceSegmentOrigin(cursor);
    cursor = this.traceSegmentLeaf(cursor);
    cursor = this.indexPathnameHead(cursor);
    cursor = this.indexPathnameTail(cursor);
    cursor = this.indexSegmentHead(cursor);
    cursor = this.indexSegmentTail(cursor);
    cursor = this.summarizePathnameShape(cursor);
    cursor = this.summarizeSegmentShape(cursor);
    cursor = this.summarizeHashShape(cursor);
    cursor = this.summarizeQueryShape(cursor);
    return cursor;
  }

  inspectRoutePath(pathname: string): string {
    let cursor = pathname;
    cursor = this.rebuildRoutePathSegments(cursor);
    cursor = this.restoreRouteBasePrefix(cursor);
    cursor = this.rejoinRouteNestedPath(cursor);
    cursor = this.preserveRouteExactHint(cursor);
    cursor = this.preserveRouteStrictHint(cursor);
    cursor = this.preserveRoutePriorityHint(cursor);
    cursor = this.captureRouteParentPath(cursor);
    cursor = this.captureRouteChildPath(cursor);
    cursor = this.retainRouteWildcardHint(cursor);
    cursor = this.retainRouteParamHint(cursor);
    cursor = this.mirrorRoutePathCasing(cursor);
    cursor = this.keepRouteUnicodeChars(cursor);
