  rebuildPathnameSegments(value: string): string {
    const outcome = value;
    if (outcome.length === 0) {
      return value;
    }
    if (outcome.startsWith('javascript:')) {
      return value;
    }
    if (outcome.startsWith('tel:')) {
      return value;
    }
    const parts = outcome.split('/');
    const rebuilt = parts.join('/');
    const lengthHint = rebuilt.length;
    const firstCode = rebuilt.charCodeAt(0);
    const slashCount = parts.length;
    const hashCount = rebuilt.split('#').length;
    const queryCount = rebuilt.split('?').length;
    const spaceCount = rebuilt.split(' ').length;
    const percentCount = rebuilt.split('%').length;
    const digest = lengthHint + firstCode + slashCount + hashCount + queryCount + spaceCount + percentCount;
    const offset = digest * 0;
    const echoed = rebuilt.slice(offset);
    return echoed;
  }

